import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaSearch,
  FaMapMarkerAlt,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
  FaCheckCircle,
  FaTimesCircle,
  FaRedo,
  FaPlayCircle,
  FaTrashAlt,
} from "react-icons/fa";

import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";
import Loader from "./LoaderComponent";
import { Link } from "react-router-dom";

const API_URL = "https://iranaserviceapp.ir/test/api";

const CLEAR_IMAGE_URL =
  "https://iranaserviceapp.ir/test/files/clear";

const PERSIAN_DIGITS = "۰۱۲۳۴۵۶۷۸۹";

function toPersianDigits(value) {
  if (value === null || value === undefined) {
    return "";
  }

  return String(value).replace(
    /\d/g,
    (digit) => PERSIAN_DIGITS[Number(digit)]
  );
}

function formatDate(dateString) {
  if (!dateString) {
    return "—";
  }

  const parts = String(dateString).split("/");

  if (parts.length !== 3) {
    return dateString;
  }

  const year = Number(parts[0]);
  const month = Number(parts[1]);
  const day = Number(parts[2]);

  if (year < 1700) {
    return `${toPersianDigits(year)}/${toPersianDigits(
      String(month).padStart(2, "0")
    )}/${toPersianDigits(
      String(day).padStart(2, "0")
    )}`;
  }

  try {
    const date = new Date(year, month - 1, day);

    return new Intl.DateTimeFormat("fa-IR-u-ca-persian", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    }).format(date);
  } catch (error) {
    console.error("DATE FORMAT ERROR:", error);
    return dateString;
  }
}

function getRequestStatus(request, clear) {
  const status = Number(request.status);
  const end = Number(request.end);
  const cleared = Number(request.cleared);
  const deleted = Number(request.deleted);

  if (clear !== null && clear !== undefined) {
    return {
      type: "settled",
      text: "تسویه شده",
      className: "text-primary fw-semibold",
      icon: <FaCheckCircle />,
    };
  }

  if (deleted === 1 || (status === 4 && end === 2)) {
    return {
      type: "admin_deleted",
      text: "حذف توسط ادمین",
      className: "text-danger fw-semibold",
      icon: <FaTrashAlt />,
    };
  }

  if (status === -1) {
    return {
      type: "canceled",
      text: "کنسل توسط تعمیرکار",
      className: "text-danger fw-semibold",
      icon: <FaTimesCircle />,
    };
  }

  if (status === 1 && end === 2) {
    return {
      type: "reactivated",
      text: "مجدد فعالسازی شده",
      className: "text-dark fw-semibold",
      icon: <FaRedo />,
    };
  }

  if (status === 1 && end === 1 && cleared === 1) {
    return {
      type: "settled",
      text: "تسویه شده",
      className: "text-primary fw-semibold",
      icon: <FaCheckCircle />,
    };
  }

  if (status === 1 && end === 1 && cleared === 0) {
    return {
      type: "waiting_payment",
      text: "تمام شده و منتظر پرداخت",
      className: "text-success fw-semibold",
      icon: <FaCoins />,
    };
  }

  if (status === 1 && end === 0) {
    return {
      type: "running",
      text: "درحال اجرا",
      className: "text-warning fw-semibold",
      icon: <FaPlayCircle />,
    };
  }

  return {
    type: "unknown",
    text: "وضعیت نامشخص",
    className: "text-muted fw-semibold",
    icon: <FaExclamationCircle />,
  };
}

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
      error: "",
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleChat = this.handleChat.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  getRequestDetail = async () => {
    const { id } = this.props.params;

    const token = localStorage.getItem("token");

    console.log("REQUEST ID:", id);

    if (!id) {
      this.setState({
        loading: false,
        error: "شناسه درخواست پیدا نشد.",
      });

      return;
    }

    if (!token) {
      this.setState({
        loading: false,
        error: "توکن ورود پیدا نشد.",
      });

      return;
    }

    const url =
      `${API_URL}/detail?id=${encodeURIComponent(id)}`;

    console.log("REQUEST DETAIL URL:", url);

    try {
      const response = await fetch(url, {
        method: "GET",
        headers: {
          Accept: "application/json",
          Authorization: `Bearer ${token}`,
        },
      });

      console.log("HTTP STATUS:", response.status);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();

      console.log("REQUEST DETAIL API:", data);

      if (String(data.status) !== "1") {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error:
            data.message ||
            "اطلاعات درخواست پیدا نشد.",
        });

        return;
      }

      const request = data.request || null;
      const clear = data.clear || null;

      if (!request) {
        this.setState({
          request: null,
          clear: null,
          loading: false,
          error: "درخواست پیدا نشد.",
        });

        return;
      }

      this.setState({
        request,
        clear,
        loading: false,
        error: "",
      });
    } catch (error) {
      console.error(
        "GET REQUEST DETAIL ERROR:",
        error
      );

      this.setState({
        request: null,
        clear: null,
        loading: false,
        error:
          "خطا در دریافت اطلاعات درخواست.",
      });
    }
  };

  handleBack() {
    this.props.navigate(-1);
  }

  handleChat() {
    console.log("رفتن به گفتگو");
  }

  handleCopyRequestCode = async () => {
    const { request } = this.state;

    if (!request?.code) {
      return;
    }

    try {
      await navigator.clipboard.writeText(
        String(request.code)
      );
    } catch (error) {
      console.error(
        "COPY REQUEST CODE ERROR:",
        error
      );
    }
  };

  render() {
    const {
      authenticated,
      request,
      clear,
      loading,
      error,
    } = this.state;

    if (!authenticated) {
      return null;
    }

    if (loading) {
      return <Loader />;
    }

    if (error) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-danger">
            {error}
          </div>
        </div>
      );
    }

    if (!request) {
      return (
        <div
          dir="rtl"
          className="container px-3 py-5"
        >
          <div className="text-center text-muted">
            درخواست پیدا نشد.
          </div>
        </div>
      );
    }

    const technician = request.repairman_model;

    const technicianName = technician
      ? `${technician.name || ""} ${
          technician.family || ""
        }`.trim()
      : "—";

    const requestStatus = getRequestStatus(
      request,
      clear
    );

    const totalReceived = Number(
      request.sum || 0
    );

    const suppliesCost = Number(
      request.abzar || 0
    );

    const totalFee =
      totalReceived - suppliesCost;

    const commissionPercent = 50;

    const commissionAmount =
      Number(totalFee / 2 || 0);

    const receiptImage =
      request.file1 &&
      request.file1 !== ""
        ? `${CLEAR_IMAGE_URL}/${request.file1}`
        : null;

    const relatedRequests =
      Array.isArray(request.siblings)
        ? request.siblings
        : [];

    return (
      <>
        <style>
          {`
            .info-field-left-icon {
              direction: ltr;
            }

            .info-field-left-icon > div,
            .info-field-left-icon > span {
              direction: rtl;
            }

            .info-action-button {
              width: 34px;
              height: 34px;
              padding: 0;
              display: flex;
              align-items: center;
              justify-content: center;
              flex-shrink: 0;
            }

            .info-action-button:hover {
              background-color: #f8f9fa;
            }
          `}
        </style>

        <div dir="rtl">
          <div className="container px-3 pt-4 pb-5">

            <div className="d-flex align-items-center justify-content-between mb-4">
              <button
                type="button"
                onClick={this.handleBack}
                className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
                style={{
                  width: 36,
                  height: 36,
                }}
              >
                <FaChevronLeft size={14} />
              </button>

              <button
                type="button"
                onClick={this.handleChat}
                className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center text-danger"
                style={{
                  width: 36,
                  height: 36,
                }}
              >
                <FaCommentDots size={16} />
              </button>
            </div>

            {/* شماره درخواست */}
            <div className="info-field-left-icon">
              <InfoField
                icon={<FaClone size={18} />}
                label="شماره درخواست"
                value={request.code || "—"}
              />

              {request.code && (
                <button
                  type="button"
                  onClick={this.handleCopyRequestCode}
                  className="d-none"
                />
              )}
            </div>

            {/* نسخه شماره درخواست با دکمه کپی */}
            <div
              className="border rounded-4 px-3 py-3 mb-3 bg-white d-flex align-items-center"
              style={{
                direction: "ltr",
                gap: 12,
              }}
            >
              <div
                className="text-primary"
                style={{ opacity: 0.75 }}
              >
                <FaClone size={18} />
              </div>

              <span
                className="text-muted"
                style={{
                  direction: "rtl",
                  whiteSpace: "nowrap",
                }}
              >
                شماره درخواست:
              </span>

              <span
                className="text-dark flex-grow-1"
                style={{
                  direction: "rtl",
                  textAlign: "right",
                }}
              >
                {request.code || "—"}
              </span>

              {request.code && (
                <button
                  type="button"
                  onClick={this.handleCopyRequestCode}
                  className="btn btn-light border rounded-3 info-action-button"
                  title="کپی شماره درخواست"
                >
                  <FaClone size={14} />
                </button>
              )}
            </div>

            {/* تعمیرکار */}
            <div
              className="border rounded-4 px-3 py-3 mb-3 bg-white d-flex align-items-center"
              style={{
                direction: "ltr",
                gap: 12,
              }}
            >
              <div
                className="text-primary"
                style={{ opacity: 0.75 }}
              >
                <FaUserCog size={18} />
              </div>

              <span
                className="text-muted"
                style={{
                  direction: "rtl",
                  whiteSpace: "nowrap",
                }}
              >
                نام تعمیرکار:
              </span>

              <span
                className="text-dark flex-grow-1"
                style={{
                  direction: "rtl",
                  textAlign: "right",
                }}
              >
                {technicianName}
              </span>

              {technician?.id && (
                <Link
                  to={`/PersonalInfoPage/${technician.id}`}
                  className="btn btn-light border rounded-3 text-primary text-decoration-none info-action-button"
                  title="مشاهده پروفایل تعمیرکار"
                >
                  <span
                    className="d-flex align-items-center justify-content-center position-relative"
                    style={{ width: 18, height: 18 }}
                  >
                    <FaUserCog size={14} />
                    <FaSearch
                      size={7}
                      className="position-absolute bg-white rounded-circle"
                      style={{
                        right: -2,
                        bottom: -1,
                      }}
                    />
                  </span>
                </Link>
              )}
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaUserEdit size={18} />}
                label="نام مشتری"
                value={request.name || "—"}
              />
            </div>

            {/* شماره تماس */}
            <div
              className="border rounded-4 px-3 py-3 mb-3 bg-white d-flex align-items-center"
              style={{
                direction: "ltr",
                gap: 12,
              }}
            >
              <div
                className="text-primary"
                style={{ opacity: 0.75 }}
              >
                <FaPhoneAlt size={18} />
              </div>

              <span
                className="text-muted"
                style={{
                  direction: "rtl",
                  whiteSpace: "nowrap",
                }}
              >
                شماره تماس:
              </span>

              <span
                className="text-dark flex-grow-1"
                style={{
                  direction: "rtl",
                  textAlign: "right",
                }}
              >
                {request.mobile || "—"}
              </span>

              {request.mobile && (
                <a
                  href={`tel:${request.mobile}`}
                  className="btn btn-light border rounded-3 text-success text-decoration-none info-action-button"
                  title="تماس"
                >
                  <FaPhone size={14} />
                </a>
              )}
            </div>

            {/* تلفن ثابت */}
            <div
              className="border rounded-4 px-3 py-3 mb-3 bg-white d-flex align-items-center"
              style={{
                direction: "ltr",
                gap: 12,
              }}
            >
              <div
                className="text-primary"
                style={{ opacity: 0.75 }}
              >
                <FaPhone size={18} />
              </div>

              <span
                className="text-muted"
                style={{
                  direction: "rtl",
                  whiteSpace: "nowrap",
                }}
              >
                تلفن ثابت:
              </span>

              <span
                className="text-dark flex-grow-1"
                style={{
                  direction: "rtl",
                  textAlign: "right",
                }}
              >
                {request.mobile2 || "—"}
              </span>

              {request.mobile2 && (
                <a
                  href={`tel:${request.mobile2}`}
                  className="btn btn-light border rounded-3 text-success text-decoration-none info-action-button"
                  title="تماس"
                >
                  <FaPhone size={14} />
                </a>
              )}
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaMapMarkerAlt size={18} />}
                label="استان"
                value={
                  request.state_model?.name || "—"
                }
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaMapMarkerAlt size={18} />}
                label="آدرس"
                value={request.address || "—"}
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaMicrochip size={18} />}
                label="نوع دستگاه"
                value={
                  request.device_type || "—"
                }
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaTag size={18} />}
                label="برند دستگاه"
                value={
                  request.device_brand || "—"
                }
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaQuestionCircle size={18} />}
                label="ایراد دستگاه"
                value={
                  request.problem || "—"
                }
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaClock size={18} />}
                label="زمان مراجعه"
                value={formatDate(request.time)}
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={<FaSyncAlt size={18} />}
                label="توضیحات"
                value={
                  request.description || "—"
                }
              />
            </div>

            <div className="info-field-left-icon">
              <InfoField
                icon={requestStatus.icon}
                label="وضعیت"
              >
                <span
                  className={
                    requestStatus.className
                  }
                >
                  {requestStatus.text}
                </span>
              </InfoField>
            </div>

            {request.end_description && (
              <div className="info-field-left-icon">
                <InfoField
                  icon={
                    <FaExclamationCircle size={18} />
                  }
                  label="توضیحات وضعیت"
                  value={request.end_description}
                />
              </div>
            )}

            {clear && (
              <>
                <div className="info-field-left-icon">
                  <InfoField
                    icon={<FaCoins size={18} />}
                    label="کل دریافتی"
                  >
                    <span className="fw-semibold">
                      {totalReceived.toLocaleString(
                        "fa-IR"
                      )}{" "}
                      تومان
                    </span>
                  </InfoField>
                </div>

                <div className="info-field-left-icon">
                  <InfoField
                    icon={<FaCoins size={18} />}
                    label="هزینه لوازم مصرفی"
                  >
                    <span className="fw-semibold">
                      {suppliesCost.toLocaleString(
                        "fa-IR"
                      )}{" "}
                      تومان
                    </span>
                  </InfoField>
                </div>

                <div className="info-field-left-icon">
                  <InfoField
                    icon={<FaBoxOpen size={18} />}
                    label="لوازم مصرفی"
                    value={
                      request.abzar_details || "—"
                    }
                  />
                </div>

                <div className="info-field-left-icon">
                  <InfoField
                    icon={<FaFileInvoice size={18} />}
                    label="کل اجرت"
                  >
                    <span className="fw-semibold">
                      {totalFee.toLocaleString(
                        "fa-IR"
                      )}{" "}
                      تومان
                    </span>
                  </InfoField>
                </div>

                <div className="info-field-left-icon">
                  <InfoField
                    icon={<FaFileInvoice size={18} />}
                    label={`پورسانت (%${commissionPercent})`}
                  >
                    <span className="fw-semibold">
                      {commissionAmount.toLocaleString(
                        "fa-IR"
                      )}{" "}
                      تومان
                    </span>
                  </InfoField>
                </div>

                {receiptImage && (
                  <div
                    className="d-flex align-items-center justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white"
                    style={{
                      direction: "rtl",
                    }}
                  >
                    <span className="text-muted">
                      فیش واریزی:
                    </span>

                    <img
                      src={receiptImage}
                      alt="فیش واریزی"
                      className="rounded-3 border"
                      style={{
                        width: 140,
                        height: 110,
                        objectFit: "cover",
                        cursor: "pointer",
                      }}
                    />
                  </div>
                )}

                <div className="info-field-left-icon">
                  <InfoField
                    icon={
                      <FaExclamationCircle size={18} />
                    }
                    label="توضیحات تایید تسویه"
                    value={
                      clear.description ||
                      clear.desc ||
                      "—"
                    }
                  />
                </div>
              </>
            )}

            <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
              درخواست‌های مرتبط:
            </h2>

            {relatedRequests.length === 0 ? (
              <div className="text-center text-muted py-4">
                هنوز موردی برای نمایش وجود ندارد.
              </div>
            ) : (
              <div>
                {relatedRequests.map(
                  (related) => (
                    <Link
                      key={related.id}
                      to={`/request-details/${related.id}`}
                      className="text-decoration-none text-dark"
                    >
                      <div className="border rounded-3 p-3 mb-2 text-end">
                        {related.code ||
                          related.id}
                      </div>
                    </Link>
                  )
                )}
              </div>
            )}

            <Link
              to="/form"
              state={{
                relatedRequest: request,
              }}
              className="btn btn-primary w-100 rounded-3 py-3 mt-2 text-white text-decoration-none"
            >
              افزودن درخواست مرتبط
            </Link>
          </div>
        </div>
      </>
    );
  }
}

export default withRouter(RequestDetailPage);
